-- Migración 0025. LOTES_UBICACIONES_TIPOS nace con ORIGEN, DESTINO (ID 2) y XDOCK.
-- Un lote tiene como mucho un DESTINO. Se recibe solo si es suelto y el
-- destino coincide con la ubicación de la recepción. Un lote recibido no
-- puede pasar a tener padre.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

BEGIN;

CREATE TABLE "LOTES_UBICACIONES_TIPOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now()
);

INSERT INTO "LOTES_UBICACIONES_TIPOS" ("ID", "CODIGO", "NOMBRE", "ES_SEMILLA") VALUES
  (1, 'ORIGEN', 'Origen', true),
  (2, 'DESTINO', 'Destino', true),
  (3, 'XDOCK', 'Xdock', true);

SELECT setval(
  pg_get_serial_sequence('"LOTES_UBICACIONES_TIPOS"', 'ID'),
  (SELECT MAX("ID") FROM "LOTES_UBICACIONES_TIPOS")
);

CREATE TRIGGER "LOTES_UBICACIONES_TIPOS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "LOTES_UBICACIONES_TIPOS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

ALTER TABLE "LOTES_UBICACIONES_TIPOS" OWNER TO packing;

CREATE TABLE "LOTES_UBICACIONES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_LOTE" integer NOT NULL,
  "UBICACION_ID" integer NOT NULL,
  "ID_TIPO" integer NOT NULL,
  "USUARIO_ID" integer,
  "ID_ORIGEN_USUARIO" integer,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "LOTES_UBICACIONES_ID_LOTE_FK"
    FOREIGN KEY ("ID_LOTE") REFERENCES "LOTES" ("ID"),
  CONSTRAINT "LOTES_UBICACIONES_UBICACION_ID_FK"
    FOREIGN KEY ("UBICACION_ID") REFERENCES "UBICACIONES" ("ID"),
  CONSTRAINT "LOTES_UBICACIONES_ID_TIPO_FK"
    FOREIGN KEY ("ID_TIPO") REFERENCES "LOTES_UBICACIONES_TIPOS" ("ID"),
  CONSTRAINT "LOTES_UBICACIONES_ID_ORIGEN_USUARIO_FK"
    FOREIGN KEY ("ID_ORIGEN_USUARIO") REFERENCES "USUARIOS_ORIGENES" ("ID"),
  CONSTRAINT "LOTES_UBICACIONES_LOTE_TIPO_UBICACION_UQ"
    UNIQUE ("ID_LOTE", "ID_TIPO", "UBICACION_ID"),
  CONSTRAINT "LOTES_UBICACIONES_USUARIO_ID_CHK" CHECK ("USUARIO_ID" > 0),
  CONSTRAINT "LOTES_UBICACIONES_USUARIO_ORIGEN_CHK" CHECK (
    ("USUARIO_ID" IS NULL) = ("ID_ORIGEN_USUARIO" IS NULL)
  )
);

CREATE UNIQUE INDEX "LOTES_UBICACIONES_DESTINO_UQ"
  ON "LOTES_UBICACIONES" ("ID_LOTE")
  WHERE "ID_TIPO" = 2;

CREATE INDEX "LOTES_UBICACIONES_UBICACION_ID_IDX"
  ON "LOTES_UBICACIONES" ("UBICACION_ID");

CREATE INDEX "LOTES_UBICACIONES_ID_TIPO_IDX"
  ON "LOTES_UBICACIONES" ("ID_TIPO");

CREATE INDEX "LOTES_UBICACIONES_ID_ORIGEN_USUARIO_IDX"
  ON "LOTES_UBICACIONES" ("ID_ORIGEN_USUARIO");

CREATE TRIGGER "LOTES_UBICACIONES_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "LOTES_UBICACIONES"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE TRIGGER "LOTES_UBICACIONES_USUARIO_REF_TRG"
  BEFORE INSERT OR UPDATE ON "LOTES_UBICACIONES"
  FOR EACH ROW
  EXECUTE FUNCTION usuario_referencia_validar();

ALTER TABLE "LOTES_UBICACIONES" OWNER TO packing;

CREATE TABLE "RECEPCIONES_LOTES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_RECEPCION" integer NOT NULL,
  "ID_LOTE" integer NOT NULL UNIQUE,
  "OBSERVACIONES" text,
  "USUARIO_ID" integer,
  "ID_ORIGEN_USUARIO" integer,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "RECEPCIONES_LOTES_ID_RECEPCION_FK"
    FOREIGN KEY ("ID_RECEPCION") REFERENCES "RECEPCIONES" ("ID"),
  CONSTRAINT "RECEPCIONES_LOTES_ID_LOTE_FK"
    FOREIGN KEY ("ID_LOTE") REFERENCES "LOTES" ("ID"),
  CONSTRAINT "RECEPCIONES_LOTES_ID_ORIGEN_USUARIO_FK"
    FOREIGN KEY ("ID_ORIGEN_USUARIO") REFERENCES "USUARIOS_ORIGENES" ("ID"),
  CONSTRAINT "RECEPCIONES_LOTES_OBSERVACIONES_CHK" CHECK (
    "OBSERVACIONES" IS NULL OR length(btrim("OBSERVACIONES")) > 0
  ),
  CONSTRAINT "RECEPCIONES_LOTES_USUARIO_ID_CHK" CHECK ("USUARIO_ID" > 0),
  CONSTRAINT "RECEPCIONES_LOTES_USUARIO_ORIGEN_CHK" CHECK (
    ("USUARIO_ID" IS NULL) = ("ID_ORIGEN_USUARIO" IS NULL)
  )
);

CREATE INDEX "RECEPCIONES_LOTES_ID_RECEPCION_IDX"
  ON "RECEPCIONES_LOTES" ("ID_RECEPCION");

CREATE INDEX "RECEPCIONES_LOTES_ID_ORIGEN_USUARIO_IDX"
  ON "RECEPCIONES_LOTES" ("ID_ORIGEN_USUARIO");

CREATE OR REPLACE FUNCTION recepciones_lotes_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  ubicacion_recepcion integer;
  padre_id integer;
  destino_id integer;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  SELECT "UBICACION_ID" INTO ubicacion_recepcion
  FROM "RECEPCIONES"
  WHERE "ID" = NEW."ID_RECEPCION";

  IF NOT FOUND THEN
    RAISE EXCEPTION 'recepcion inexistente' USING ERRCODE = '23503';
  END IF;

  SELECT "PADRE_ID" INTO padre_id
  FROM "LOTES"
  WHERE "ID" = NEW."ID_LOTE";

  IF NOT FOUND THEN
    RAISE EXCEPTION 'lote inexistente' USING ERRCODE = '23503';
  END IF;

  IF padre_id IS NOT NULL THEN
    RAISE EXCEPTION 'solo se reciben lotes sin padre' USING ERRCODE = '23514';
  END IF;

  SELECT relacion."UBICACION_ID" INTO destino_id
  FROM "LOTES_UBICACIONES" AS relacion
  JOIN "LOTES_UBICACIONES_TIPOS" AS tipo ON tipo."ID" = relacion."ID_TIPO"
  WHERE relacion."ID_LOTE" = NEW."ID_LOTE"
    AND tipo."CODIGO" = 'DESTINO';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'el lote no tiene destino' USING ERRCODE = '23514';
  END IF;

  IF destino_id IS DISTINCT FROM ubicacion_recepcion THEN
    RAISE EXCEPTION 'el destino del lote no coincide con la recepcion'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER "RECEPCIONES_LOTES_TRG"
  BEFORE INSERT OR UPDATE OR DELETE ON "RECEPCIONES_LOTES"
  FOR EACH ROW
  EXECUTE FUNCTION recepciones_lotes_validar();

CREATE TRIGGER "RECEPCIONES_LOTES_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "RECEPCIONES_LOTES"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE TRIGGER "RECEPCIONES_LOTES_USUARIO_REF_TRG"
  BEFORE INSERT OR UPDATE ON "RECEPCIONES_LOTES"
  FOR EACH ROW
  EXECUTE FUNCTION usuario_referencia_validar();

ALTER TABLE "RECEPCIONES_LOTES" OWNER TO packing;
ALTER FUNCTION recepciones_lotes_validar() OWNER TO packing;

CREATE OR REPLACE FUNCTION lotes_validar()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  tipo_final boolean;
  padre_final boolean;
BEGIN
  SELECT "ES_FINAL" INTO tipo_final
  FROM "LOTES_TIPOS"
  WHERE "ID" = NEW."ID_TIPO";

  IF tipo_final IS NULL THEN
    RAISE EXCEPTION 'tipo de lote inexistente' USING ERRCODE = '23503';
  END IF;

  IF tipo_final THEN
    IF NEW."ID_UNIDAD" IS NOT NULL THEN
      RAISE EXCEPTION 'un lote final no se embarca en la unidad' USING ERRCODE = '23514';
    END IF;

    IF NEW."PADRE_ID" IS NOT NULL THEN
      IF EXISTS (
        SELECT 1
        FROM "EXPEDICIONES_LOTES"
        WHERE "ID_LOTE" = NEW."ID"
      ) THEN
        RAISE EXCEPTION 'un lote embarcado no puede tener padre' USING ERRCODE = '23514';
      END IF;

      IF EXISTS (
        SELECT 1
        FROM "RECEPCIONES_LOTES"
        WHERE "ID_LOTE" = NEW."ID"
      ) THEN
        RAISE EXCEPTION 'un lote recibido no puede tener padre' USING ERRCODE = '23514';
      END IF;

      SELECT tipo."ES_FINAL" INTO padre_final
      FROM "LOTES" AS padre
      JOIN "LOTES_TIPOS" AS tipo ON tipo."ID" = padre."ID_TIPO"
      WHERE padre."ID" = NEW."PADRE_ID";

      IF padre_final IS NULL THEN
        RAISE EXCEPTION 'lote padre inexistente' USING ERRCODE = '23503';
      END IF;

      IF padre_final THEN
        RAISE EXCEPTION 'una categoria final no contiene lotes' USING ERRCODE = '23514';
      END IF;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW."ID_TIPO" IS DISTINCT FROM OLD."ID_TIPO" THEN
      IF EXISTS (SELECT 1 FROM "LOTES" WHERE "PADRE_ID" = NEW."ID") THEN
        RAISE EXCEPTION 'una categoria final no contiene lotes' USING ERRCODE = '23514';
      END IF;

      IF EXISTS (
        SELECT 1
        FROM "LOTES_PRODUCTOS" AS producto
        WHERE producto."ID_LOTE" = NEW."ID"
          AND NOT EXISTS (
            SELECT 1
            FROM "LOTES_TIPOS_UNIDADES" AS relacion
            WHERE relacion."ID_TIPO" = NEW."ID_TIPO"
              AND relacion."ID_UNIDAD" = producto."ID_UNIDAD"
          )
      ) THEN
        RAISE EXCEPTION 'la medida del producto no corresponde al tipo de lote' USING ERRCODE = '23514';
      END IF;
    END IF;
  ELSE
    IF NEW."PADRE_ID" IS NOT NULL THEN
      RAISE EXCEPTION 'solo un lote final puede ir dentro de otro lote' USING ERRCODE = '23514';
    END IF;

    IF EXISTS (SELECT 1 FROM "LOTES_PRODUCTOS" WHERE "ID_LOTE" = NEW."ID") THEN
      RAISE EXCEPTION 'un lote que no es final no contiene productos' USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION lotes_validar() OWNER TO packing;

COMMIT;
